// Copyright (c) 2026 Roshan. All rights reserved.// Proprietary license — see LICENSE file for details.package com.roshan.persona.ui.navigationimport androidx.compose.foundation.backgroundimport androidx.compose.foundation.layout.Boximport androidx.compose.foundation.layout.Columnimport androidx.compose.foundation.layout.fillMaxSizeimport androidx.compose.foundation.layout.paddingimport androidx.compose.material3.ExperimentalMaterial3Apiimport androidx.compose.material3.MaterialThemeimport androidx.compose.material3.ModalBottomSheetimport androidx.compose.material3.rememberModalBottomSheetStateimport androidx.compose.runtime.Composableimport androidx.compose.runtime.LaunchedEffectimport androidx.compose.runtime.collectAsStateimport androidx.compose.runtime.getValueimport androidx.compose.runtime.mutableStateOfimport androidx.compose.runtime.rememberimport androidx.compose.runtime.rememberCoroutineScopeimport androidx.compose.runtime.setValueimport androidx.compose.ui.Modifierimport androidx.compose.ui.unit.dpimport androidx.navigation.compose.NavHostimport androidx.navigation.compose.composableimport androidx.navigation.compose.rememberNavControllerimport com.roshan.persona.ui.components.NavTabimport com.roshan.persona.ui.components.NousBottomNavimport com.roshan.persona.ui.screens.AppLockScreenimport com.roshan.persona.ui.screens.BrainActivitySheetimport com.roshan.persona.ui.screens.HomeScreenimport com.roshan.persona.ui.screens.MemoryScreenimport com.roshan.persona.ui.screens.PersonaSummaryimport com.roshan.persona.ui.screens.PersonaSwitcherSheetimport com.roshan.persona.ui.screens.SettingsEntryimport com.roshan.persona.ui.screens.SettingsGroupimport com.roshan.persona.ui.screens.SettingsScreenimport com.roshan.persona.ui.screens.SkillsScreenimport com.roshan.persona.ui.screens.SkillSummaryimport com.roshan.persona.ui.screens.AutomationRuleSummaryimport com.roshan.persona.ui.screens.VisionModeimport com.roshan.persona.ui.screens.VisionScreenimport com.roshan.persona.ui.state.UiStateProviderimport kotlinx.coroutines.launch/** * Navigation routes. */object NousRoutes {    const val Splash = "splash"    const val AppLock = "app_lock"    const val Home = "home"    const val Vision = "vision"    const val Skills = "skills"    const val Settings = "settings"    const val Memory = "memory"}/** * Main navigation host — wires all screens together. * * @param stateProvider Hilt-injected UI state provider * @param personas list of available personas (from BuiltInPersonas) * @param activePersonaId current active persona ID * @param onPersonaSelected callback when user picks a persona * @param skills list of available skills (from SkillRegistry) * @param automationRules list of automation rules * @param onSkillClick callback when a skill is tapped * @param onCreateAutomation callback to create new automation * @param onToggleAutomation callback to toggle rule * @param settingsGroups settings menu structure * @param onSettingsEntryClick callback when settings entry tapped * @param isMicListening whether mic is capturing * @param onMicClick toggle mic * @param onCapture capture photo (vision) * @param onFlipCamera flip camera (vision) * @param lastVisionResult last vision result description * @param biometricAvailable for App Lock * @param onBiometricUnlock trigger biometric * @param onPinSubmit PIN submit * @param onUsePasskey switch to passkey * @param attemptsRemaining for App Lock * @param lockoutMs for App Lock * @param appVersion for splash * @param buildNumber for splash * @param safeMode for splash * @param integrityVerified for splash * @param initProgress for splash * @param initStepDescription for splash * @param onSplashFinished navigate past splash * @param isLocked whether App Lock should be shown */@OptIn(ExperimentalMaterial3Api::class)@Composablefun NousNavHost(    stateProvider: UiStateProvider,    viewModel: com.roshan.persona.ui.state.NousViewModel,    personas: List<PersonaSummary>,    activePersonaId: String,    activePersonaName: String,    activePersonaTagline: String,    onPersonaSelected: (String) -> Unit,    skills: List<SkillSummary>,    automationRules: List<AutomationRuleSummary>,    onSkillClick: (SkillSummary) -> Unit,    onCreateAutomation: () -> Unit,    onToggleAutomation: (AutomationRuleSummary) -> Unit,    settingsGroups: List<SettingsGroup>,    onSettingsEntryClick: (SettingsEntry) -> Unit,    isMicListening: Boolean,    onMicClick: () -> Unit,    onCapture: () -> Unit,    onFlipCamera: () -> Unit,    lastVisionResult: String?,    biometricAvailable: Boolean,    onBiometricUnlock: () -> Unit,    onPinSubmit: (String) -> Unit,    onUsePasskey: () -> Unit,    attemptsRemaining: Int,    lockoutMs: Long,    appVersion: String,    buildNumber: String,    safeMode: Boolean,    integrityVerified: Boolean?,    initProgress: Float,    initStepDescription: String,    onSplashFinished: () -> Unit,    isLocked: Boolean,    userName: String,    modifier: Modifier = Modifier,) {    val navController = rememberNavController()    var activeTab by remember { mutableStateOf(NavTab.Home) }    var showBrainSheet by remember { mutableStateOf(false) }    var showPersonaSheet by remember { mutableStateOf(false) }    var onAttachClick by remember { mutableStateOf({}) }    val scope = rememberCoroutineScope()    // Start destination    LaunchedEffect(Unit) {        if (isLocked) {            navController.navigate(NousRoutes.AppLock) {                popUpTo(0)            }        }    }    Column(        modifier = modifier            .fillMaxSize()            .background(MaterialTheme.colorScheme.background),    ) {        Box(modifier = Modifier.weight(1f)) {            NavHost(                navController = navController,                startDestination = NousRoutes.Splash,            ) {                composable(NousRoutes.Splash) {                    com.roshan.persona.ui.screens.SplashScreen(                        initProgress = initProgress,                        initStepDescription = initStepDescription,                        safeMode = safeMode,                        integrityVerified = integrityVerified,                        appVersion = appVersion,                        buildNumber = buildNumber,                        onFinished = {                            if (isLocked) {                                navController.navigate(NousRoutes.AppLock) {                                    popUpTo(NousRoutes.Splash) { inclusive = true }                                }                            } else {                                navController.navigate(NousRoutes.Home) {                                    popUpTo(NousRoutes.Splash) { inclusive = true }                                }                            }                            onSplashFinished()                        },                    )                }                composable(NousRoutes.AppLock) {                    AppLockScreen(                        userName = userName,                        biometricAvailable = biometricAvailable,                        onBiometricUnlock = {                            onBiometricUnlock()                            // On successful unlock, host should call back to navigate home.                            // For simplicity, we navigate immediately — real unlock state                            // is owned by AppLockManager.                        },                        onPinSubmit = { pin ->                            onPinSubmit(pin)                        },                        onUsePasskey = onUsePasskey,                        attemptsRemaining = attemptsRemaining,                        lockoutMs = lockoutMs,                    )                }                composable(NousRoutes.Home) {                    HomeScreen(                        stateProvider = stateProvider,                        activePersonaId = activePersonaId,                        activePersonaName = activePersonaName,                        activePersonaTagline = activePersonaTagline,                        onBrainBarClick = { showBrainSheet = true },                        onPersonaSwitcherClick = { showPersonaSheet = true },                        onMicClick = onMicClick,                        onAttachClick = { /* Opens attachment options: camera, file, location, contact */ },                        isMicListening = isMicListening,                    )                }                composable(NousRoutes.Vision) {                    VisionScreen(                        modes = VisionMode.entries.toList(),                        activeMode = VisionMode.OCR,                        onModeSelected = { mode -> /* Switches vision mode: OCR, Document, Objects, Faces, Barcode, Screen */ },                        onCapture = onCapture,                        onFlipCamera = onFlipCamera,                        lastResultDescription = lastVisionResult,                        stateProvider = stateProvider,                    )                }                composable(NousRoutes.Skills) {                    SkillsScreen(                        skills = skills,                        automationRules = automationRules,                        onSkillClick = onSkillClick,                        onCreateAutomation = onCreateAutomation,                        onToggleAutomation = onToggleAutomation,                    )                }                composable(NousRoutes.Settings) {                    SettingsScreen(                        groups = settingsGroups,                        onEntryClick = onSettingsEntryClick,                        stateProvider = stateProvider,                    )                }                composable(NousRoutes.Memory) {                    MemoryScreen(stateProvider = stateProvider)                }            }        }        // Bottom nav (only on Home/Vision/Skills/Settings, not on Splash/AppLock)        val currentRoute = navController.currentDestination?.route        if (currentRoute in listOf(NousRoutes.Home, NousRoutes.Vision, NousRoutes.Skills, NousRoutes.Settings)) {            NousBottomNav(                activeTab = activeTab,                onTabSelected = { tab ->                    activeTab = tab                    val route = when (tab) {                        NavTab.Home -> NousRoutes.Home                        NavTab.Vision -> NousRoutes.Vision                        NavTab.Skills -> NousRoutes.Skills                        NavTab.Settings -> NousRoutes.Settings                    }                    navController.navigate(route) {                        launchSingleTop = true                        popUpTo(NousRoutes.Home) { saveState = true }                        restoreState = true                    }                },                onMicClick = onMicClick,                isListening = isMicListening,            )        }        // Brain Activity bottom sheet        if (showBrainSheet) {            val sheetState = rememberModalBottomSheetState(skipPartiallyExpanded = true)            ModalBottomSheet(                onDismissRequest = { showBrainSheet = false },                sheetState = sheetState,                containerColor = MaterialTheme.colorScheme.surface,            ) {                BrainActivitySheet(stateProvider = stateProvider)            }        }        // Persona Switcher bottom sheet        if (showPersonaSheet) {            val sheetState = rememberModalBottomSheetState(skipPartiallyExpanded = true)            ModalBottomSheet(                onDismissRequest = { showPersonaSheet = false },                sheetState = sheetState,                containerColor = MaterialTheme.colorScheme.surface,            ) {                PersonaSwitcherSheet(                    personas = personas,                    activePersonaId = activePersonaId,                    onPersonaSelected = { id ->                        onPersonaSelected(id)                        scope.launch {                            showPersonaSheet = false                        }                    },                )            }        }    }}